solution:
fn safe_deref_add(a: *Int, b: *Int) -> Int
  requires: a != null;
  requires: b != null;
{
  return a + b;
}

fn main() -> Int {
  let x = 10;
  let y = 32;
  return safe_deref_add(&x, &y);
}
